    'RegisterSimpleRisk'=>'Реєстрація SimpleRisk',
    'RegistrationText'=>'Зареєстровані екземпляри SimpleRisk відразу отримують доступ до Extras «Upgrade» та «Secure Controls Framework (SCF)». Extra «Upgrade» дає можливість створити резервну копію та виконати оновлення вашого екземпляра SimpleRisk одним натисканням кнопки. Extra «Secure Controls Framework (SCF)» надає єдиний фреймворк контролів, інтегрований у функціональність Управління SimpleRisk. Під час реєстрації SimpleRisk ваша реєстраційна інформація буде надіслана на сервер, що розміщується SimpleRisk. Надана реєстраційна інформація використовуватиметься SimpleRisk для сповіщення клієнтів про нові випуски та оновлення безпеки. Реєстрація SimpleRisk означає вашу згоду на отримання наших маркетингових повідомлень, але ви можете в будь-який час відмовитися від них за допомогою посилання для скасування підписки в цих повідомленнях. SimpleRisk поважає конфіденційність наших клієнтів, а інформація, яку ви надаєте нам під час реєстрації SimpleRisk, ніколи не буде продана третім особам.',
