    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Налаштуйте параметри всієї системи: базову URL-адресу, безпеку, мову за замовчуванням, часовий пояс, параметри оцінки ризиків за замовчуванням тощо.',
    'SettingsPreferencesDesc'             => 'Значення за замовчуванням і поведінкові уподобання в SimpleRisk: мова, часовий пояс, статуси аудиту, вимоги до зіставлення ризиків, перемикачі поведінки інтерфейсу тощо.',
    'SettingsFileUploadDesc'              => 'Дозволені типи файлів для завантаження та обмеження розміру для різних полів вкладення файлів.',
    'SettingsMailDesc'                    => 'Конфігурація SMTP для вихідних сповіщень електронною поштою, зокрема транспорт, вузол, автентифікація та адреса для відповіді.',
    'SettingsBackupsDesc'                 => 'Налаштуйте зберігання резервних копій, розклад і посилання для завантаження резервних копій бази даних SimpleRisk.',
    'SettingsSecurityDesc'                => 'Налаштування автентифікації, сеансу, політики паролів, базової URL-адреси та безпеки API.',
    'SettingsLoggingDesc'                 => 'Конфігурація журналювання налагодження та аудиту: рівні журналювання, зберігання та розташування файлів журналів.',
    'HealthCheckDesc'                     => 'Діагностика статусу системи: версія PHP, розширення, дозволи на файли, підключення до бази даних, розклад cron та активації Extra.',
    'AnnouncementsDesc'                   => 'Створюйте та керуйте банерними оголошеннями, видимими для всіх користувачів.',
    'RegisterAndUpgradeDesc'              => 'Зареєструйте свою інсталяцію SimpleRisk, введіть або поновіть ключ підписки та активуйте оновлення Core/Extra одним клацанням миші.',
    'QueueMonitorDesc'                    => 'Перегляд черги фонових завдань: завдання в очікуванні, у виконанні та невдалі завдання.',
    'ExtrasDesc'                          => 'Активуйте, деактивуйте та налаштуйте SimpleRisk Extras (платні доповнення).',
    'ArtificialIntelligenceExtraDesc'     => 'Додатковий модуль штучного інтелекту забезпечує розширений аналіз ризиків (включаючи оцінки FAIR) та індивідуальну документацію.',
    'CustomizationExtraDesc'              => 'Extra «Кастомізація» дає можливість додавати та видаляти різні типи полів і динамічно створювати користувацькі шаблони сторінок.',
    'NotificationExtraDesc'               => 'Додаткова функція сповіщення електронною поштою дозволяє SimpleRisk надсилати сповіщення електронною поштою, коли ризики надсилаються, змінюються або з ними вживаються інші дії. Цю додаткову функцію також можна додати як запланований скрипт для надсилання регулярних нагадувань, коли ризики готові до перевірки керівництвом. У продукті SimpleRisk Core без цієї додаткової функції жодні сповіщення не передаються за межі самого інструменту.',
    'VulnerabilityManagementExtraDesc'    => 'Extra «Управління вразливостями» дає клієнтам можливість інтегрувати свій екземпляр SimpleRisk із Qualys, Tenable.io або Rapid7 Nexpose/InsightVM та імпортувати до SimpleRisk дані як про активи, так і про вразливості. Звідти ви можете вибрати, які сайти охопити, визначити, які оцінки вразливостей імпортувати, і відібрати, які вразливості перетворюються на ризики для їх відстеження.',
    'IncidentManagementExtraDesc'         => 'Додатковий модуль управління інцидентами базується на Посібнику з обробки інцидентів комп\'ютерної безпеки NIST 800-61 та надає можливості управління інцидентами всередині системи SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Перейменуйте термінологію SimpleRisk (ризик, актив, фреймворк тощо) в усьому інтерфейсі.',
    'RiskConfigurationDesc'               => 'Налаштуйте правила оцінки ризику: рівні, схильність до ризику, порогові значення SLA та класичні формули ризику / формули з урахуванням факторів впливу.',
    'RiskAndThreatCatalogDesc'            => 'Ведіть каталог значень ризиків і загроз, що використовуються у випадаючих списках.',
    'AddAndRemoveValuesDesc'              => 'Керування значеннями випадних списків для полів ризику: розташування, джерело, категорія, команда, технологія тощо.',
    'AssetValuationDesc'                  => 'Налаштуйте шкалу оцінювання активів і перевизначення оцінки для окремих активів.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Додавайте, редагуйте, вимикайте та скидайте користувачів; керуйте політикою паролів.',
    'RoleManagementDesc'                  => 'Визначте ролі та дозволи, які надає кожна роль.',
    'TeamManagementDesc'                  => 'Створення та керування командами, що використовуються для фільтрації видимості записів.',
    'SeparationExtraDesc'                 => 'Додаткова функція розділення на основі команди обмежує перегляд ризиків лише користувачами, які є членами команди, якій призначено ризик. У продукті SimpleRisk Core, без цієї додаткової функції, кожен користувач може бачити кожен ризик.',
    'CustomAuthenticationExtraDesc'       => 'Extra «Користувацька автентифікація» забезпечує підтримку автентифікації Active Directory та SAML. У продукті SimpleRisk Core без цього Extra єдиний варіант — створювати нових користувачів у сховищі ідентифікацій SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Extra «Зашифрована база даних» генерує випадковий 256-бітний ключ шифрування AES, а потім використовує його для шифрування конфіденційного тексту перед його вставленням у базу даних SimpleRisk. Це не дозволяє будь-кому переглядати чи змінювати дані без прямого використання застосунку SimpleRisk.',
    'OrganizationManagementDesc'          => 'Extra «Організаційна ієрархія» дає можливість визначати кілька підрозділів, які можуть включати будь-яку кількість команд. Користувачів можна призначати до однієї чи кількох команд у різних підрозділах. Це впливає на здатність користувача бачити та використовувати команди, користувачів і активи, з якими він не пов\'язаний.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Масове видалення ризиків. Використовуйте обережно — видалення незворотні.',
    'AuditTrailDesc'                      => 'Пошук та експорт журналу системного аудиту дій користувачів.',
    'ImportExportExtraDesc'               => 'Extra «Імпорт-експорт» дає можливість імпортувати дані до SimpleRisk шляхом зіставлення полів файлу CSV з полями бази даних SimpleRisk. Його можна використовувати для імпорту результатів аудиту зі стороннього файлу електронної таблиці, результатів сканування вразливостей з іншого інструмента, активів із вашої CMDB тощо. Цей Extra також дає змогу експортувати з SimpleRisk файли CSV, що містять ризики, пом\'якшення, перегляди або комбінований звіт з усіх трьох.',
    'JiraExtraDesc'                       => 'Extra «Інтеграція з Jira» дає користувачам можливість двосторонньої інтеграції з екземпляром Jira. Він дозволяє пов\'язувати ризики із завданнями Jira, а також синхронізувати їхні дані, статус і коментарі.',
    'APIExtraDesc'                        => 'Extra «API» дозволяє клієнтам використовувати RESTful API для створення скриптових взаємодій з іншими застосунками, щоб отримати розширену автоматизацію та використати наявну інфраструктуру.',
    'AdvancedSearchExtraDesc'             => "Додаток «Розширений пошук» перетворює поле пошуку у верхній панелі на єдиний пошук за ризиками, фреймворками, елементами контролю, документами, винятками, тестами, аудитами, активами та групами активів, з повноцінною сторінкою пошуку для роботи з результатами. Він відображає лише ті записи, які користувач має право переглядати.",
    'AssessmentsExtraDesc'                => 'Extra «Оцінка ризиків» дає користувачам можливість визначати контакти, створювати запитання (зокрема з логікою), збирати кілька запитань у шаблон анкети, створювати анкети та надсилати їх контактам, переглядати результати анкет, додавати ризики на основі цих результатів, порівнювати результати з часом, імпортувати й експортувати зовнішні користувацькі оцінки та переглядати журнал аудиту оцінки ризиків.',
    'ActiveAssessmentsDesc'               => 'Переглядайте та керуйте оцінюваннями, які зараз тривають.',
    'WorkflowsExtraDesc'                  => 'Extra «Робочі процеси» надає візуальний, керований подіями рушій робочих процесів, який автоматизує дії з управління ризиками у відповідь на події в SimpleRisk. Ви можете розробляти робочі процеси, що запускаються при змінах — наприклад, коли ризик подано, оновлено чи переглянуто — щоб маршрутизувати погодження, призначати роботу та підтримувати рух процесу без ручного втручання.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Secure Controls Framework (SCF) Extra — це пряма інтеграція між Secure Controls Framework і SimpleRisk. Вона імпортує каталог контролів SCF та їх зіставлення з широким спектром фреймворків відповідності та кібербезпеки до функціоналу Управління SimpleRisk, щоб ви могли впроваджувати потрібні фреймворки та керувати їхніми контролями, не створюючи їх вручну.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Перенесення застарілих стовпців дат перегляду типу varchar до відповідних типів дати. Відображається лише за потреби.',
    'DatabaseUpgradeDesc'                 => 'Вручну запустіть процедуру оновлення бази даних SimpleRisk.',

