    'EncryptionRestoreCtaHelp'              => 'Виберіть цей варіант, якщо перевірка виявила проблеми й потрібно повернутися до стану до шифрування.',
    'EncryptionRestoreTitle'                => 'Відновити з резервної копії?',
    'EncryptionRestoreBodyWhy'              => 'Повернення до знімка стану до шифрування, зробленого на початку останньої активації. Виберіть цей варіант, якщо під час перевірки після активації було виявлено проблеми, і вам потрібно відмовитися від шифрування.',
    'EncryptionRestoreBodyWhat'             => 'Кожен рядок, записаний до бази даних після створення резервної копії, буде безповоротно втрачено, зокрема ризики, пом\'якшення, записи журналу аудиту та будь-які інші зміни, внесені після активації. Розширення «Зашифрована база даних» буде деактивовано в межах відновлення.',
    'EncryptionDeleteBackupCta'             => 'Видалити резервну копію до шифрування',
    'EncryptionDeleteBackupCtaHelp'         => 'Виберіть цей варіант, коли перевірку після шифрування буде завершено. Саме видалення незашифрованого знімка робить шифрування справді захисним.',
    'EncryptionDeleteBackupTitle'           => 'Видалити резервну копію до шифрування?',
    'EncryptionDeleteBackupBodyWhy'         => 'Видалення незашифрованого знімка ваших даних, створеного на початку останньої активації. Необмежене зберігання суперечить меті шифрування — будь-хто з доступом до бази даних може прочитати копію до шифрування.',
    'EncryptionDeleteBackupBodyWhat'        => 'Резервну копію в базі даних буде видалено негайно. Ви більше не зможете використовувати функцію «Відновити з резервної копії», щоб повернути базу даних до стану до шифрування. Якщо пізніше ви виявите проблеми із шифруванням, єдиним способом відновлення буде повне відновлення бази даних із ваших робочих резервних копій.',
    'EncryptionDeleteBackupError'           => 'Не вдалося видалити резервну копію. Перевірте журнал налагодження та спробуйте ще раз.',
