    'AssetScoring' => 'Оцінка активів',
    'AssetScoringSettingsHint' => 'Кожному активу присвоюється рейтинг «Низький», «Помірний» або «Високий» за конфіденційністю, цілісністю та доступністю, а конфіденційність натомість може бути «Не застосовується», що виключає її з обох результатів. FIPS-категоризація активу — це найвищий із трьох рейтингів. Зважена оцінка активу — це середній зважений показник трьох значень рівнів, а порогові значення діапазонів перетворюють цю оцінку на діапазон «Низький», «Помірний» або «Високий». Зміна цих налаштувань негайно перераховує оцінку кожного активу.',
    'Weights' => 'Ваги',
    'AssetScoringWeightsHint' => 'Наскільки кожна ціль впливає на зважену оцінку: від 0 до 100, до двох десяткових знаків. Вага 0 виключає цю ціль. Цілісність і доступність не можуть одночасно дорівнювати 0, оскільки конфіденційність зі значенням «Не застосовується» завжди виключається.',
    'LevelValues' => 'Значення рівнів',
    'AssetScoringLevelValuesHint' => 'Число, яке кожен рейтинг додає до зваженої оцінки: більше 0 і до 100, до двох десяткових знаків, причому «Низький» менший за «Помірний», а «Помірний» менший за «Високий». Значення за замовчуванням: «Низький» 1, «Помірний» 2 і «Високий» 3.',
    'BandThresholds' => 'Порогові значення діапазонів',
    'AssetScoringBandThresholdsHint' => 'Зважена оцінка, що дорівнює порогу або перевищує його, належить до відповідного діапазону, а оцінка нижче порогу «Помірний» належить до діапазону «Низький». Діапазон «Помірний» має починатися вище значення «Низький», а «Високий» — вище «Помірного» і не вище значення «Високий».',
    'ModerateStartsAt' => 'Помірний починається з',
