    'UserImportPasswordsUnavailable' => 'Тимчасові паролі більше не можна показати. Вони показуються один раз, лише адміністратору, який розпочав імпорт, і лише у вкладці браузера, де його розпочато, а SimpleRisk не зберігає нічого, що дозволило б показати їх ще раз. Встановіть новий пароль для кожного нового користувача, відредагувавши користувача.',
    'UserImportBackgroundNote' => 'Ця сторінка оновлюється самостійно, а імпорт продовжується, якщо ви залишите її. Відкрийте сторінку знову, щоб побачити результат.',
    'AuditAdditionalStakeholdersSetOnTest' => 'Додаткові зацікавлені сторони задаються в тесті. Щоб змінити їх, відредагуйте тест у розділі {$page}; зміна одразу застосовується до цього аудиту.',
    'QuestionnaireDraftSomeFilesNotSaved' => 'Ваші відповіді збережено, але одне або кілька вкладень не було збережено. Файл може бути занадто великим або недозволеного типу.',
