    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Увімкнути сувору безпеку транспортування HTTP (HSTS)',
    'EnableHSTSHelp' => 'Вказує браузерам підключатися до SimpleRisk лише через HTTPS протягом зазначеного нижче максимального терміну дії. Вмикайте це лише після того, як HTTPS стабільно працює на цьому сайті: браузери, які отримали цей заголовок, відмовлятимуться від звичайного HTTP, а несправний сертифікат неможливо буде обійти, доки не мине максимальний термін дії. Почніть з короткого терміну, наприклад 300 секунд, і збільште його після перевірки HTTPS.',
    'HSTSMaxAge' => 'Максимальний термін дії HSTS (секунди)',
