    'HSTSIncludeSubdomains' => 'Застосувати HSTS до всіх піддоменів',
    'HSTSIncludeSubdomainsHelp' => 'Також примусово вмикає HTTPS для кожного субдомену цього хоста. Залиште вимкненим, якщо будь-який субдомен обслуговується через звичайний HTTP.',
